// Выносим обработку ответа в отдельную функцию
function handle_copy_positions_response(frm, r) {
    console.log('Full server response:', r); // Для отладки
    
    // Проверяем корректность структуры ответа
    if (!r || !r.message || !r.message.data) {
        console.error('Invalid response structure:', r);
        frappe.show_alert({
            message: __('Некорректный формат ответа от сервера'),
            indicator: 'red'
        }, 5);
        return;
    }

    const result = r.message.data;
    let message = '';
    let indicator = 'orange';

    // Формируем информативное сообщение
    if (result.copied_count > 0) {
        message = __('Успешно скопировано: {0}', [result.copied_count]);
        indicator = 'green';
        
        if (result.duplicates_count > 0 || result.invalid_count > 0) {
            message += '\n'; // Перенос строки
        }
    }
    
    if (result.duplicates_count > 0) {
        message += __('Пропущено дубликатов: {0}', [result.duplicates_count]);
        if (result.invalid_count > 0) {
            message += '\n'; // Перенос строки
        }
    }
    
    if (result.invalid_count > 0) {
        message += __('Пропущено невалидных: {0}', [result.invalid_count]);
    }
    
    if (!message) {
        message = __('Нет позиций для копирования');
    }

    // Показываем уведомление
    frappe.show_alert({
        message: message,
        indicator: indicator
    }, 8);
}

// Функция для обработки ошибок
function handle_copy_positions_error(frm, err) {
    console.error('Request error:', err);
    frappe.show_alert({
        message: __('Ошибка при обработке запроса'),
        indicator: 'red'
    }, 5);
}

function render_copied_positions(frm, positions, customers, fullDates, filteredHolidays) {
    if (!positions || positions.length === 0) return;
    
    positions.forEach(position => {
        position.new = true;
        createNewRow(position, customers, frm, fullDates, filteredHolidays);
    });
    
    loadPositionsTitles( frm.ts_positions );
    timesheetDataUpdated();
}

//Тикет -- ISS-2025-01495
function disableCopyPosition( frm ) {
    if (frm.doc.ut_status != 'На доработке' && frm.doc.ut_status != 'Черновик') {
        frm.remove_custom_button("Позиции из предыдущего ТШ", frappe.utils.icon("sidebar-expand") + __(" Скопировать") );
    }
}

// Новая функция для обработки кнопки копирования позиций + отрисовка кнопки
function addCopyPositionsButton(frm, customers, fullDates, filteredHolidays) {
    frm.add_custom_button(
        __('Позиции из предыдущего ТШ'),
        () => handleCopyPositions(frm, customers, fullDates, filteredHolidays),
        frappe.utils.icon("sidebar-expand") + __(" Скопировать")
    );
}

function handleCopyPositions(frm, customers, fullDates, filteredHolidays) {
    disableCopyPosition(frm);
    frappe.call({
        method: 'copy_positions_from_previous_timesheet',
        args: { doc: frm.doc },
        freeze: true,
        silent: true,
        callback: function(r) {
            handle_copy_positions_response(frm, r);
            
            if (r.message?.success && r.message.data?.positions?.length > 0) {
                render_copied_positions(
                    frm, 
                    r.message.data.positions, 
                    customers, 
                    fullDates, 
                    filteredHolidays
                );
            }
        },
        error: function(err) {
            handle_copy_positions_error(frm, err);
        }
    });
}
